<?php
namespace Tests\Feature; use App\Models\Quote; use App\Models\User; use Illuminate\Foundation\Testing\RefreshDatabase; use Tests\TestCase;
class QuoteManagementTest extends TestCase { use RefreshDatabase; public function test_guest_can_view_quotes():void{$q=Quote::factory()->create(['content'=>'Visible inspiration']);$this->get('/')->assertOk()->assertSee('Visible inspiration')->assertSee($q->user->name);} public function test_guest_cannot_add_quote():void{$this->post('/quotes',['content'=>'Not allowed'])->assertRedirect('/login');} public function test_user_can_add_quote():void{$u=User::factory()->create();$this->actingAs($u)->post('/quotes',['content'=>'A valid new quote'])->assertRedirect();$this->assertDatabaseHas('quotes',['user_id'=>$u->id,'content'=>'A valid new quote']);} public function test_owner_can_edit_quote():void{$q=Quote::factory()->create();$this->actingAs($q->user)->put('/quotes/'.$q->id,['content'=>'Updated quote'])->assertRedirect('/');$this->assertDatabaseHas('quotes',['id'=>$q->id,'content'=>'Updated quote']);} public function test_other_user_cannot_edit_quote():void{$q=Quote::factory()->create();$this->actingAs(User::factory()->create())->put('/quotes/'.$q->id,['content'=>'Stolen'])->assertForbidden();$this->assertDatabaseMissing('quotes',['id'=>$q->id,'content'=>'Stolen']);} public function test_owner_can_delete_quote():void{$q=Quote::factory()->create();$this->actingAs($q->user)->delete('/quotes/'.$q->id)->assertRedirect();$this->assertDatabaseMissing('quotes',['id'=>$q->id]);} public function test_other_user_cannot_delete_quote():void{$q=Quote::factory()->create();$this->actingAs(User::factory()->create())->delete('/quotes/'.$q->id)->assertForbidden();$this->assertDatabaseHas('quotes',['id'=>$q->id]);} public function test_search_finds_matching_quote():void{Quote::factory()->create(['content'=>'Laravel makes elegant apps']);Quote::factory()->create(['content'=>'Another thought']);$this->get('/?q=Laravel')->assertOk()->assertSee('Laravel makes elegant apps')->assertDontSee('Another thought');} public function test_quote_validation():void{$u=User::factory()->create();$this->actingAs($u)->post('/quotes',['content'=>'ab'])->assertSessionHasErrors('content');$this->actingAs($u)->post('/quotes',['content'=>str_repeat('x',156)])->assertSessionHasErrors('content');} }
